import { readFileSync } from 'node:fs'

export interface GetRoutesFromTypedRouterOptions {
  /**
   * When true, dynamic routes (those containing `:param` or `*` segments)
   * are kept. By default, they are filtered out since their params need
   * to be expanded to concrete values before being useful in a sitemap.
   * @default false
   */
  includeDynamic?: boolean
}

/**
 * Parse a `typed-router.d.ts` file generated by vue-router (v5+) or
 * unplugin-vue-router and return the list of route paths (using
 * vue-router's `:param` syntax).
 *
 * Static routes are returned by default; dynamic routes (with `:param`
 * or `*` segments) are filtered out unless `includeDynamic` is `true`.
 */
export function getRoutesFromTypedRouter(
  filePath: string,
  options: GetRoutesFromTypedRouterOptions = {},
): string[] {
  const content = readFileSync(filePath, 'utf-8')

  const body = extractRouteNamedMapBody(content)
  if (body === null)
    return []

  const regex = /RouteRecordInfo<\s*'[^']+'\s*,\s*'([^']+)'/g
  const routes: string[] = []
  let match: RegExpExecArray | null
  // eslint-disable-next-line no-cond-assign
  while ((match = regex.exec(body)))
    routes.push(match[1])

  if (options.includeDynamic)
    return routes
  return routes.filter(route => !/[:*]/.test(route))
}

function extractRouteNamedMapBody(content: string): string | null {
  const header = content.match(/interface\s+RouteNamedMap\s*\{/)
  if (!header || header.index === undefined)
    return null
  const start = header.index + header[0].length
  let depth = 1
  for (let i = start; i < content.length; i++) {
    const ch = content[i]
    if (ch === '{')
      depth++
    else if (ch === '}' && --depth === 0)
      return content.slice(start, i)
  }
  return null
}
